auto simpson_rule = [&](double a, double b) {
        double c = (a + b) / 2.0;
        return (std::abs(b - a) / 6.0) * (f(a) + 4.0 * f(c) + f(b));
    };

    std::function<double(double, double, double, double)> recursive_simpson = 
        [&](double a, double b, double eps, double whole) -> double {
        double c = (a + b) / 2.0;
        double left = simpson_rule(a, c);
        double right = simpson_rule(c, b);
        if (std::abs(left + right - whole) <= 15.0 * eps) {
            return left + right + (left + right - whole) / 15.0;
        }
        return recursive_simpson(a, c, eps / 2.0, left) + 
               recursive_simpson(c, b, eps / 2.0, right);
    };

    return recursive_simpson(a, b, precision, simpson_rule(a, b));

